const settings = $input.first().json;
const normalizeDatabaseId = (value) => {
  const raw = String(value || '').trim();
  const compact = raw.replace(/-/g, '');
  const match = compact.match(/[0-9a-fA-F]{32}/);
  return match ? match[0] : raw;
};
return settings.trades.map((trade) => ({
  json: {
    trade,
    textQuery: `${trade} Handwerksbetrieb Karlsruhe`,
    city: settings.city,
    center: settings.center,
    radiusMeters: settings.radiusMeters,
    maxResults: settings.maxPerTrade,
    notionDatabaseId: normalizeDatabaseId(settings.notionDatabaseInput)
  }
}));

const items = $input.all();
const normalizePhone = (value) => String(value || '').replace(/[^0-9+]/g, '');
const normalizeDomain = (value) => {
  try {
    if (!value) return '';
    const url = new URL(String(value).startsWith('http') ? value : `https://${value}`);
    return url.hostname.replace(/^www\./, '').toLowerCase();
  } catch (e) { return ''; }
};
const normalizeText = (value) => String(value || '').toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]+/g, ' ').trim();
const getCity = (address, fallback) => {
  const parts = String(address || '').split(',').map(p => p.trim()).filter(Boolean);
  const karlsruhe = parts.find(p => /karlsruhe/i.test(p));
  return karlsruhe || fallback || '';
};
const candidates = [];
let found = 0;
let searchErrors = 0;
for (const item of items) {
  const json = item.json || {};
  if (json.error || Number(json.statusCode || 200) >= 400) searchErrors += 1;
  const places = Array.isArray(json.places) ? json.places : (Array.isArray(json.body?.places) ? json.body.places : []);
  found += places.length;
  for (const place of places) {
    const companyName = place.displayName?.text || place.displayName || place.name || '';
    const website = place.websiteUri || '';
    const phone = place.nationalPhoneNumber || place.internationalPhoneNumber || '';
    const city = getCity(place.formattedAddress, json.city);
    const domain = normalizeDomain(website);
    const phoneKey = normalizePhone(phone);
    const nameCityKey = `${normalizeText(companyName)}|${normalizeText(city)}`;
    candidates.push({
      placeId: place.id || place.name || '',
      companyName,
      trade: json.trade || '',
      city,
      address: place.formattedAddress || '',
      website,
      domain,
      phone,
      phoneKey,
      email: '',
      googleMapsUrl: place.googleMapsUri || '',
      businessStatus: place.businessStatus || '',
      nameCityKey,
      source: 'Google Places',
      notionDatabaseId: json.notionDatabaseId || '',
      searchErrors
    });
  }
}
const seen = new Set();
const unique = [];
let internalDuplicates = 0;
for (const c of candidates) {
  const keys = [c.placeId && `place:${c.placeId}`, c.domain && `domain:${c.domain}`, c.phoneKey && `phone:${c.phoneKey}`, c.nameCityKey && `namecity:${c.nameCityKey}`].filter(Boolean);
  const duplicate = keys.some(key => seen.has(key));
  if (duplicate) { internalDuplicates += 1; continue; }
  keys.forEach(key => seen.add(key));
  unique.push(c);
}
return unique.map((c) => ({ json: { ...c, runMetrics: { foundBusinesses: found, internalDuplicates, searchErrors } } }));

const normalizePhone = (value) => String(value || '').replace(/[^0-9+]/g, '');
const normalizeDomain = (value) => {
  try { if (!value) return ''; const url = new URL(String(value).startsWith('http') ? value : `https://${value}`); return url.hostname.replace(/^www\./, '').toLowerCase(); } catch (e) { return ''; }
};
const normalizeText = (value) => String(value || '').toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]+/g, ' ').trim();
const propText = (props, name) => {
  const p = props?.[name];
  if (!p) return '';
  if (p.title) return p.title.map(x => x.plain_text || x.text?.content || '').join('');
  if (p.rich_text) return p.rich_text.map(x => x.plain_text || x.text?.content || '').join('');
  if (p.url) return p.url;
  if (p.phone_number) return p.phone_number;
  if (p.email) return p.email;
  if (p.select) return p.select.name || '';
  if (p.number !== undefined) return String(p.number);
  return String(p.plain_text || '');
};
const crmResponse = $input.first()?.json || {};
const crmLoadFailed = !!crmResponse.error || Number(crmResponse.statusCode || 200) >= 400;
const pages = Array.isArray(crmResponse.body?.results) ? crmResponse.body.results : (Array.isArray(crmResponse.results) ? crmResponse.results : []);
const existing = new Set();
for (const page of pages) {
  const props = page.properties || {};
  const company = propText(props, 'Firmenname');
  const city = propText(props, 'Ort');
  const website = propText(props, 'Website');
  const phone = propText(props, 'Telefon');
  const placeId = propText(props, 'Google Place ID');
  const domain = normalizeDomain(website);
  const phoneKey = normalizePhone(phone);
  const nameCityKey = `${normalizeText(company)}|${normalizeText(city)}`;
  [placeId && `place:${placeId}`, domain && `domain:${domain}`, phoneKey && `phone:${phoneKey}`, nameCityKey && `namecity:${nameCityKey}`].filter(Boolean).forEach(k => existing.add(k));
}
const candidates = $('Normalize Places and Remove Internal Duplicates').all().map(i => i.json);
let crmDuplicates = 0;
const newLeads = [];
for (const c of candidates) {
  const keys = [c.placeId && `place:${c.placeId}`, c.domain && `domain:${c.domain}`, c.phoneKey && `phone:${c.phoneKey}`, c.nameCityKey && `namecity:${c.nameCityKey}`].filter(Boolean);
  const isDuplicate = keys.some(k => existing.has(k));
  if (isDuplicate) { crmDuplicates += 1; continue; }
  newLeads.push({ ...c, runMetrics: { ...(c.runMetrics || {}), crmDuplicates, notionLoadErrors: crmLoadFailed ? 1 : 0, loadedCrmPages: pages.length } });
}
return newLeads.map(lead => ({ json: lead }));

const response = $json || {};
const statusCode = Number(response.statusCode || response.status || 0);
const rawBody = typeof response.body === 'string' ? response.body : (typeof response.data === 'string' ? response.data : JSON.stringify(response.body || response.data || ''));
const reachable = !response.error && statusCode >= 200 && statusCode < 400 && rawBody.length > 0;
const text = rawBody.replace(/<script[\s\S]*?<\/script>/gi, ' ').replace(/<style[\s\S]*?<\/style>/gi, ' ').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 12000);
const emailMatch = rawBody.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i);
const lower = text.toLowerCase();
const hasCta = /(kontakt|angebot|termin|anfrage|beratung|notdienst)/i.test(text);
const hasServices = /(leistungen|service|sanitär|heizung|dach|maler|elektro|reinigung|garten|landschaft)/i.test(text);
return { json: { websiteReachable: reachable, websiteStatusCode: statusCode || '', websiteText: text, websiteEmail: emailMatch ? emailMatch[0] : '', websiteSignals: { hasCta, hasServices, mentionsKontakt: lower.includes('kontakt'), textLength: text.length }, websiteFetchError: response.error?.message || response.message || '' } };

