const allowed = new Set(['Hoch', 'Mittel', 'Niedrig']);
const fallback = { warumInteressant: 'OpenAI-Analyse fehlgeschlagen oder nicht verfügbar.', groessteWebsiteSchwaeche: 'Keine belastbare Aussage möglich.', landingpagePotenzial: 'Niedrig', automationsPotenzial: 'Niedrig', landingpageChance: 'Keine belastbare Aussage möglich.', automationsChance: 'Keine belastbare Aussage möglich.', besterVerkaufsansatz: 'Manuell prüfen.', websiteScore: 0, openAiError: true };
let out = $json.output ?? $json;
if (typeof out === 'string') { try { out = JSON.parse(out); } catch (e) { out = null; } }
if (!out || $json.error) return { json: fallback };
const normalized = { ...fallback, ...out, openAiError: false };
if (!allowed.has(normalized.landingpagePotenzial)) normalized.landingpagePotenzial = 'Niedrig';
if (!allowed.has(normalized.automationsPotenzial)) normalized.automationsPotenzial = 'Niedrig';
normalized.websiteScore = Math.max(0, Math.min(100, Number(normalized.websiteScore || 0)));
return { json: normalized };

const potentialValue = (v) => v === 'Hoch' ? 30 : v === 'Mittel' ? 20 : 10;
const clamp = (n) => Math.max(0, Math.min(100, Math.round(Number(n) || 0)));
const websiteReachable = !!$json.websiteReachable;
const websiteScore = websiteReachable ? clamp($json.websiteScore) : 0;
const landing = $json.landingpagePotenzial || 'Niedrig';
const automation = $json.automationsPotenzial || 'Niedrig';
const contactCompleteness = ($json.phone ? 5 : 0) + (($json.websiteEmail || $json.email) ? 5 : 0) + ($json.website ? 5 : 0);
const weaknessBonus = websiteScore < 50 ? 15 : websiteScore < 70 ? 8 : 2;
const opportunityScore = clamp(potentialValue(landing) + potentialValue(automation) + contactCompleteness + weaknessBonus);
const priority = opportunityScore >= 80 ? 'A' : opportunityScore >= 60 ? 'B' : 'C';
const email = $json.websiteEmail || $json.email || '';
const mainWeakness = $json.groessteWebsiteSchwaeche || (websiteReachable ? 'Keine belastbare Aussage möglich.' : 'Website nicht erreichbar oder nicht vorhanden.');
const websiteWeaknesses = [
  `Warum interessant: ${$json.warumInteressant || 'Keine belastbare Aussage möglich.'}`,
  `Größte Website-Schwäche: ${mainWeakness}`,
  `Landingpage-Chance: ${$json.landingpageChance || 'Keine belastbare Aussage möglich.'}`,
  `Automations-Chance: ${$json.automationsChance || 'Keine belastbare Aussage möglich.'}`
].join('\n');
const offerAngle = `Bester Verkaufsansatz: ${$json.besterVerkaufsansatz || 'Manuell prüfen.'}`;
const rich = (text) => ({ rich_text: [{ text: { content: String(text || '').slice(0, 1900) } }] });
const title = (text) => ({ title: [{ text: { content: String(text || '').slice(0, 1900) } }] });
const select = (name) => ({ select: { name } });
const number = (value) => ({ number: Number(value) || 0 });
const payload = {
  parent: { database_id: $json.notionDatabaseId },
  properties: {
    'Firmenname': title($json.companyName),
    'Branche': select($json.trade || 'Unbekannt'),
    'Ort': rich($json.city || ''),
    'Website': { url: $json.website || null },
    'Telefon': { phone_number: $json.phone || null },
    'E-Mail': { email: email || null },
    'Website Score': number(websiteScore),
    'Landingpage Potenzial': select(landing),
    'Automations Potenzial': select(automation),
    'Opportunity Score': number(opportunityScore),
    'Priorität': select(priority),
    'Website Schwächen': rich(websiteWeaknesses),
    'Angebotswinkel': rich(offerAngle),
    'Status': select('Neu')
  }
};
return { json: { ...$json, email, websiteScore, landingpagePotenzial: landing, automationsPotenzial: automation, opportunityScore, priority, websiteWeaknesses, offerAngle, notionPayload: payload, processingErrors: ($json.openAiError ? 1 : 0) + ($json.websiteFetchError ? 1 : 0) } };

const prepared = $('Score and Prepare Lead').all().map(i => i.json);
const saves = $input.all().map(i => i.json);
const firstMetrics = prepared[0]?.runMetrics || $('Normalize Places and Remove Internal Duplicates').first()?.json?.runMetrics || {};
const saveErrors = saves.filter(s => s.error || Number(s.statusCode || 200) >= 400).length;
const processingErrors = prepared.reduce((sum, item) => sum + Number(item.processingErrors || 0), 0);
const summary = {
  workflow: 'HANDWERK OPPORTUNITY SYSTEM V1',
  foundBusinesses: Number(firstMetrics.foundBusinesses || 0),
  duplicates: Number(firstMetrics.internalDuplicates || 0) + Number(firstMetrics.crmDuplicates || 0),
  newBusinesses: prepared.length,
  aLeads: prepared.filter(item => item.priority === 'A').length,
  errors: Number(firstMetrics.searchErrors || 0) + Number(firstMetrics.notionLoadErrors || 0) + processingErrors + saveErrors,
  savedToNotion: saves.length - saveErrors,
  notionSaveErrors: saveErrors,
  generatedAt: new Date().toISOString(),
  requiredCredentials: ['Google Places API Key', 'OpenAI', 'Notion API'],
  openPoints: ['Workflow Settings: Notion Database ID oder URL eintragen', 'Notion-Datenbank muss mit der Integration geteilt sein', 'Notion-Feldtypen müssen zum Feldvertrag passen']
};
return [{ json: summary }];
